"""Independent reference implementation (brute force), written from the spec."""
import itertools
from fractions import Fraction

G = [[0,0,1],[1,1,2],[1,1,2]]
UNI = (Fraction(1,3),)*3

def canon(a,b): return (a,b) if a<b else (b,a)

def solve(data):
    ixps = set(data['ixps'])
    def norm(p):
        out=[]
        for a in p:
            if a in ixps: continue
            if out and out[-1]==a: continue
            out.append(a)
        return out
    agg={}
    for rec in data['rib']:
        q=norm(rec['path'])
        if len(q)<2: continue
        if len(set(q))!=len(q): continue
        agg[tuple(q)] = agg.get(tuple(q),0)+rec['count']
    links=set()
    for q in agg:
        for a,b in zip(q,q[1:]): links.add(canon(a,b))
    priors={}
    for rec in data['priors']:
        a,b = rec['link']; w=rec['weights']; s=sum(w)
        v=tuple(Fraction(x,s) for x in w)
        priors[canon(a,b)] = v if a<b else (v[2],v[1],v[0])
    decl={}
    for rec in data['declared']:
        a,b=rec['link']; r=rec['rel']; k=('c2p','p2p','p2c').index(r)
        v=[Fraction(0)]*3; v[k]=Fraction(1); v=tuple(v)
        decl[canon(a,b)] = v if a<b else (v[2],v[1],v[0])

    rnd={}; cur=dict(agg); r=0
    def pathlinks(q): return [canon(a,b) for a,b in zip(q,q[1:])]
    while cur:
        r+=1
        present=set()
        for q in cur: present.update(pathlinks(q))
        marked=set()
        for e in sorted(present):
            u,v=e; oku=True; okv=True
            for q in cur:
                if e not in pathlinks(q): continue
                if q[0]!=u and q[-1]!=u: oku=False
                if q[0]!=v and q[-1]!=v: okv=False
            if oku or okv: marked.add(e)
        if not marked: break
        for e in marked: rnd[e]=r
        nxt={}
        for q,c in cur.items():
            pl=pathlinks(q); s=0; t=len(q)
            if pl[0] in marked: s=1
            if pl[-1] in marked: t=len(q)-1
            if t-s>=2:
                k=q[s:t]; nxt[k]=nxt.get(k,0)+c
        cur=nxt
    core=sorted(links-set(rnd))
    idx={e:i for i,e in enumerate(core)}
    occ=[]
    for q,c in cur.items():
        n=len(q)
        for i in range(n-1):
            a,b=q[i],q[i+1]; e=canon(a,b)
            if a<b:
                L=(q[i-1],a) if i>0 else None
                R=(b,q[i+2]) if i+2<n else None
            else:
                L=(q[i+2],b) if i+2<n else None
                R=(a,q[i-1]) if i>0 else None
            occ.append((e,L,R,c))
    # scope graph for width validation
    scopes={}
    for e in core:
        s={idx[e]}
        for (ee,L,R,c) in occ:
            if ee!=e: continue
            for d in (L,R):
                if d is not None: s.add(idx[canon(d[0],d[1])])
        scopes[e]=sorted(s)
    order=[tuple(x) for x in data['order']]
    # validate order permutation + width
    assert sorted(order)==core, (order, core)
    adj={i:set() for i in range(len(core))}
    for e in core:
        for x in scopes[e]:
            for y in scopes[e]:
                if x!=y: adj[x].add(y); adj[y].add(x)
    live={i:set(adj[i]) for i in adj}
    ovars=[idx[tuple(x)] for x in order]
    for v in ovars:
        nb=live[v]
        assert len(nb)<=4, ("width", len(nb))
        for x in nb:
            for y in nb:
                if x!=y: live[x].add(y); live[y].add(x)
        for x in nb: live[x].discard(v)
        live[v]=set()
    def dtyp(d, assign):
        x,y=d; f=canon(x,y); t=assign[idx[f]]
        return t if x<y else 2-t
    Z=0; marg={e:[0,0,0] for e in core}
    for assign in itertools.product(range(3), repeat=len(core)):
        W=1
        for e in core:
            phi=0
            for (ee,L,R,c) in occ:
                if ee!=e: continue
                Lt=0 if L is None else dtyp(L,assign)
                Rt=2 if R is None else dtyp(R,assign)
                if assign[idx[e]]==G[Lt][Rt]: phi+=c
            W*=phi
            if W==0: break
        Z+=W
        if W:
            for e in core: marg[e][assign[idx[e]]]+=W
    if Z==0: return {'error':'zero-partition'}
    cprob={e: tuple(Fraction(x,Z) for x in marg[e]) for e in core}
    out_links=[]
    for e in sorted(links):
        rr=rnd.get(e,0)
        v=cprob[e] if rr==0 else priors.get(e,UNI)
        out_links.append({'link':[e[0],e[1]],'round':rr,'prob':[float(x) for x in v]})
    def look(e):
        if e in decl: return decl[e]
        if e in cprob: return cprob[e]
        if e in priors: return priors[e]
        return UNI
    outq=[]
    for rec in data['queries']:
        q=norm(rec['path'])
        if len(set(q))!=len(q):
            outq.append({'id':rec['id'],'path':q,'status':'loop','score':None,'full':None,'witness':None,'leaked':None})
            continue
        if len(q)<=2:
            outq.append({'id':rec['id'],'path':q,'status':'ok','score':1.0,'full':1.0,'witness':None,'leaked':False})
            continue
        vecs=[]
        for a,b in zip(q,q[1:]):
            v=look(canon(a,b))
            vecs.append(v if a<b else (v[2],v[1],v[0]))
        best=None; wit=0
        for i in range(len(vecs)-1):
            U=vecs[i][0]; D=vecs[i+1][2]
            val=U+D-U*D
            if best is None or val<best: best=val; wit=i
        # full: enumerate all type sequences
        tot=Fraction(0)
        for ts in itertools.product(range(3), repeat=len(vecs)):
            w=Fraction(1)
            for t,v in zip(ts,vecs): w*=v[t]
            if w==0: continue
            # pattern A: c2p* p2c*
            okA=True; seen_d=False
            for t in ts:
                if t==0:
                    if seen_d: okA=False;break
                elif t==2: seen_d=True
                else: okA=False;break
            okB=False
            for k in range(len(ts)):
                if all(t==0 for t in ts[:k]) and ts[k]==1 and all(t==2 for t in ts[k+1:]):
                    okB=True;break
            if okA or okB: tot+=w
        thr=Fraction(*rec['threshold'])
        outq.append({'id':rec['id'],'path':q,'status':'ok','score':float(best),'full':float(tot),'witness':wit,'leaked':best<thr})
    return {'version':1,'links':out_links,'queries':outq}
